public class HeapSort {

    public static void heapSort(int[] arr) {
        heapSort(arr, 0, arr.length);
    }

    public static void heapSort(int[] arr, int from, int to) {
        if (from < 0 || to > arr.length || from > to)
            throw new IllegalArgumentException(
                "Invalid range [" + from + ", " + to + ") for array of length " + arr.length);
        new RangeHeap(arr, from, to).sort();
    }

    static class RangeHeap {
        private final int[] arr;
        private final int from;
        private final int size;

        private RangeHeap(int[] arr, int from, int to) {
            this.arr = arr;
            this.from = from;
            this.size = to - from;
        }

        private void sort() {
            build();
            for (int i = size - 1; i > 0; i--) {
                swap(0, i);
                siftDown(0, i);
            }
        }

        private void build() {
            for (int i = size / 2 - 1; i >= 0; i--)
                siftDown(i, size);
        }

        private void siftDown(int i, int n) {
            int largest = i;
            int l = 2 * i + 1;
            int r = 2 * i + 2;
            if (l < n && get(l) > get(largest))
                largest = l;
            if (r < n && get(r) > get(largest))
                largest = r;
            if (largest != i) {
                swap(i, largest);
                siftDown(largest, n);
            }
        }

        private int get(int i) {
            return arr[from + i];
        }

        private void swap(int i, int j) {
            int temp = arr[from + i];
            arr[from + i] = arr[from + j];
            arr[from + j] = temp;
        }
    }
}

